const t=JSON.parse('{"key":"v-17174e36","path":"/posts/lesson/MIT-cs6.824-distributed-system/lesson19-bitcoin-paper.html","title":"比特币：一种点对点电子现金系统","lang":"zh-CN","frontmatter":{"category":["分布式系统"],"tag":["分布式系统"],"description":"比特币：一种点对点电子现金系统 摘要 比特币：一种点对点电子现金系统 摘要 一种纯粹的点对点电子现金版本将允许在线支付直接从一方发送到另一方，而无需经过金融机构。数字签名提供了部分解决方案，但如果仍需一个可信的第三方来防止双重支付问题，那么主要的优势就会丧失。我们提出了一种利用点对点网络解决双重支付问题的方案。","head":[["meta",{"property":"og:url","content":"https://mister-hope.github.io/posts/lesson/MIT-cs6.824-distributed-system/lesson19-bitcoin-paper.html"}],["meta",{"property":"og:site_name","content":"Code Building"}],["meta",{"property":"og:title","content":"比特币：一种点对点电子现金系统"}],["meta",{"property":"og:description","content":"比特币：一种点对点电子现金系统 摘要 比特币：一种点对点电子现金系统 摘要 一种纯粹的点对点电子现金版本将允许在线支付直接从一方发送到另一方，而无需经过金融机构。数字签名提供了部分解决方案，但如果仍需一个可信的第三方来防止双重支付问题，那么主要的优势就会丧失。我们提出了一种利用点对点网络解决双重支付问题的方案。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2024-11-13T10:03:28.000Z"}],["meta",{"property":"article:tag","content":"分布式系统"}],["meta",{"property":"article:modified_time","content":"2024-11-13T10:03:28.000Z"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"比特币：一种点对点电子现金系统\\",\\"image\\":[\\"\\"],\\"dateModified\\":\\"2024-11-13T10:03:28.000Z\\",\\"author\\":[]}"]]},"headers":[{"level":2,"title":"摘要","slug":"摘要","link":"#摘要","children":[]}],"git":{"createdTime":1730800664000,"updatedTime":1731492208000,"contributors":[{"name":"zgjsxx","email":"119160524@qq.com","commits":3}]},"readingTime":{"minutes":1.96,"words":588},"filePathRelative":"posts/lesson/MIT-cs6.824-distributed-system/lesson19-bitcoin-paper.md","localizedDate":"2024年11月5日","excerpt":"<ul>\\n<li><a href=\\"#%E6%AF%94%E7%89%B9%E5%B8%81%E4%B8%80%E7%A7%8D%E7%82%B9%E5%AF%B9%E7%82%B9%E7%94%B5%E5%AD%90%E7%8E%B0%E9%87%91%E7%B3%BB%E7%BB%9F\\">比特币：一种点对点电子现金系统</a>\\n<ul>\\n<li><a href=\\"#%E6%91%98%E8%A6%81\\">摘要</a></li>\\n</ul>\\n</li>\\n</ul>\\n<h1> 比特币：一种点对点电子现金系统</h1>\\n<h2> 摘要</h2>\\n<p>一种纯粹的点对点电子现金版本将允许在线支付直接从一方发送到另一方，而无需经过金融机构。数字签名提供了部分解决方案，但如果仍需一个可信的第三方来防止双重支付问题，那么主要的优势就会丧失。我们提出了一种利用点对点网络解决双重支付问题的方案。</p>","autoDesc":true}');export{t as data};
